 'show-signup':()=>renderAuth('signup'),'show-login':()=>renderAuth(),'close':()=>{if($('dialog').querySelector('[data-form=feature-update]')&&m.dirty&&!confirm('Descartar alterações?'))return;$('dialog').close()},
 'navigate':async e=>{await go(e.dataset.tab);$('page-title')?.focus()},'refresh':async()=>{if(m.dirty&&!confirm('Descartar alterações não salvas e atualizar?'))return;m.dirty=false;m.evalDrafts.clear();await load();if(m.tab.startsWith('sheet-'))await loadSheet();if(m.tab==='admin')await loadAdmin();if(m.tab==='development')await loadFeatures();if(m.tab==='notices')await loadNotices()},'logout':logout,
 'monthly-form':e=>monthlyForm(e.dataset.manager),'daily-form':e=>dailyForm(e.dataset.manager),'chairs-form':e=>chairsForm(e.dataset.clinic),'merit-form':e=>meritForm(e.dataset.id,e.dataset.manager),'merit-targets':e=>meritTargetsForm(e.dataset.manager),
 'daily-text':e=>{const r=m.data.daily.find(r=>r.manager===e.dataset.manager&&r.today===m.day);if(r)modal('Resumo para copiar',`<textarea id="copy-text" rows="20" readonly>${esc(dailyText(r))}</textarea>${button('copy-text','Copiar texto','',true)}`)},
 'copy-text':async()=>{try{await navigator.clipboard.writeText($('copy-text').value);toast('Texto copiado.')}catch{$('copy-text').select();toast('Use Ctrl+C para copiar.')}},
 'evaluation-mode':e=>{if(m.dirty&&!confirm('Há avaliações não salvas. Deseja trocar de visualização?'))return;m.dirty=false;m.evalDrafts.clear();m.mode=e.dataset.mode;render()},'save-evaluations':()=>saveEvaluations(),'save-evaluation-one':e=>saveEvaluations(e.dataset.clinic),
 'paste-evaluations':()=>evaluationPasteForm(),
