 if(kind==='campaign-search'){m.campaignQuery=b.query;render();return}if(kind==='campaign-plan'){if(!priv())throw Error('Somente a supervisão pode definir o objetivo.');const next=structuredClone(m.data),record={id:form.dataset.id,month:form.dataset.month,lastMonth:b.lastMonth||null,target:b.target};next.campaignPlans=(next.campaignPlans||[]).filter(p=>!(p.id===record.id&&p.month===record.month)).concat(record);await saveData(next);$('dialog').close();return}if(kind==='catalog-search'){m.search=b.query;render();return}if(kind==='sheet-search'){m.search=b.query;render();return}
 if(kind==='app-release'){await api('/api/admin/app-update','POST',{version:b.version,message:b.message,delay:Number(b.delay)});$('dialog').close();toast('Atualização obrigatória enviada para toda a equipe.');return}if(kind==='password'){await api('/api/auth/password','POST',b);clearPrivateState();renderAuth();toast('Senha alterada. Entre novamente.');return}
 if(kind==='user'){const roles=['manager','supervisor','developer'].filter(r=>form.elements.namedItem('role-'+r).checked);await api('/api/admin/users/'+form.dataset.id,'PUT',{status:b.status,manager:b.manager,roles,is_pro:form.elements.namedItem('is_pro').checked});$('dialog').close();await loadAdmin();toast('Acesso e permissões atualizados.');return}
