 if(kind==='sheet-record'){const sheet=m.seed.sheetCatalog.find(s=>s.id===m.tab),r=m.records.find(r=>r.id===form.dataset.id),data={};for(const [key,value]of Object.entries(b))if(key.startsWith('cell-'))data[key.slice(5)]=value;await api(r?'/api/records/'+r.id:'/api/sheets/'+sheet.id,r?'PUT':'POST',{data,manager:b.owner||null,version:r?.version});$('dialog').close();await loadSheet();toast('Registro salvo.');return}
 if(kind==='paste-evaluations'){if(ocrText.used&&!$('ocr-reviewed')?.checked)throw Error('Confira o texto com a imagem e marque a confirmação antes de continuar.');m.evalImport={text:b.text,corrections:{},date:b.date,period:b.period,manager:b.scope==='selected'?managerValue():null};await recheckEvaluations();return}
 const next=structuredClone(m.data);
 if(kind==='monthly'){const rows=[{metric:'Clínico geral',measure:'R$',target:num(form,'target'),actual:num(form,'actual')},{metric:'Pastas de ortodontia',measure:'Quantidade',target:num(form,'orthoTarget',true),actual:num(form,'orthoActual',true)}];next.goals=next.goals.filter(g=>!(g.unit==='manager:'+b.manager&&g.period==='mes'&&g.date===m.month&&rows.some(r=>r.metric===g.metric)));next.goals.push(...rows.map(r=>({...r,unit:'manager:'+b.manager,period:'mes',date:m.month,source:'Lançamento manual'})))}
 else if(kind==='daily'){const r={manager:b.manager,today:b.closingDay,yesterday:shiftDay(b.closingDay,-1)};for(const k of ['cgTarget','cgActual','orthoTarget','orthoActual','todayCg','todayOrtho','evalTotal','evalRequired'])r[k]=num(form,k,!['cgTarget','cgActual','todayCg'].includes(k));next.daily=next.daily.filter(x=>!(x.manager===r.manager&&x.today===r.today));next.daily.push(r)}
 else if(kind==='chairs'){const u=m.data.units.find(u=>u.id===b.id),chairs=num(form,'chairs',true),actual=num(form,'actual',true);if(!chairs)throw Error('Informe pelo menos uma cadeira.');next.chairs=next.chairs.filter(r=>!(r.id===b.id&&r.date===m.day));next.chairs.push({...u,chairs,actual,target:chairs*40,date:m.day,capturedAt:new Date().toISOString(),previous:campaignSnapshot(m.data.chairs.filter(x=>x.id===u.id&&x.date.startsWith(m.month)&&x.date<=m.day).sort((a,b)=>b.date.localeCompare(a.date))[0])})}
 else if(kind==='merit'){const r=next.merit.find(r=>r.id===form.dataset.id&&r.manager===form.dataset.manager&&r.month===m.month);if(!b.date.startsWith(m.month))throw Error('A data precisa pertencer ao mês selecionado.');r.date=b.date;for(const k of ['revenue','paid','bonus','days','recordCash'])r[k]=num(form,k,['paid','bonus','days'].includes(k))}
 else if(kind==='merit-targets'){const r={manager:form.dataset.manager,month:m.month,sourceBase:num(form,'sourceBase'),gain1Offset:num(form,'gain1Offset'),gain2Offset:num(form,'gain2Offset')};if(r.gain2Offset<r.gain1Offset)throw Error('Ganhar 2 não pode ser menor que Ganhar 1.');next.meritTargets=next.meritTargets.filter(t=>!(t.manager===r.manager&&t.month===r.month));next.meritTargets.push(r)}
